import os

from google import genai

def stream_completion(payload, config=None):
    config = config or {}
    prompt = payload["text"]
    with genai.Client(api_key=config.get("api_key") or os.environ["GOOGLE_API_KEY"]) as client:
        response_stream = client.models.generate_content(model="gemini-2.5-flash", contents=prompt, stream=True)

        full_response_content = ""
        for chunk in response_stream:
            full_response_content += chunk.text

    return {"text": full_response_content}

import os
from google import genai

def get_genai_client(config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY not found in config or environment variables.")
    return genai.Client(api_key=api_key)

def get_default_model_id():
    return "gemini-2.5-flash"

from typing import Dict, Any

def normalize_model_response(response: Any) -> Dict[str, Any]:
    """Normalizes the model response into a consistent dictionary format."""
    # This is a placeholder. Real normalization would depend on the response object structure.
    if hasattr(response, 'text'):
        return {"text": response.text}
    return {"raw_response": str(response)}

def get_model_family(model_id: str) -> str:
    """Determines the model family from the model ID."""
    if "gemini" in model_id:
        return "gemini"
    return "unknown"

import os
from google.cloud import translate_v3 as translate

def translate_text(payload, config=None):
    config = config or {}
    client = translate.TranslationServiceClient()

    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT not found in config or environment variables.")

    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload["text"]],
            "target_language_code": payload["target_language"],
        }
    )

    translated_texts = [translation.translated_text for translation in response.translations]
    return {"translated_text": translated_texts[0] if translated_texts else ""}
